/**
 * Derives the canonical region for a city using the fixed city-to-region table
 * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}). Any
 * city not in the table (including {@code null}) yields {@code "UNKNOWN"}.
 *
 * @param city the owner's city
 * @return the canonical region string, or {@code "UNKNOWN"} when the city is unknown
 */
default String locality(String city) {
    if (city == null) {
        return "UNKNOWN";
    }
    return switch (city) {
        case "Sydney" -> "NSW";
        case "Melbourne" -> "VIC";
        case "Brisbane" -> "QLD";
        default -> "UNKNOWN";
    };
}

